<div class="card"><h2>OTC \u4E3B\u52A8\u4E70\u5165\u673A\u4F1A</h2><div id="opportunity" class="small">\u7B49\u5F85\u76D8\u53E3\u7D22\u5F15\u3001\u62A5\u4EF7\u548C\u98CE\u9669\u6761\u4EF6\u3002</div><p class="small">\u201C\u5F53\u524D\u9000\u51FA\u201D\u662F\u6B64\u523B\u4E70\u76D8\u7684\u4F30\u7B97\uFF0C\u4E0D\u662F\u9501\u5B9A\u5229\u6DA6\uFF1B\u4E70\u5165\u540E\u901A\u5E38\u6302\u5356\u5355\u7B49\u5F85\u6210\u4EA4\u3002\u4E24\u79CD\u6D4B\u7B97\u90FD\u4E0D\u662F\u5DF2\u8D5A\u6536\u76CA\u3002</p></div>
